/* cppi::dc303b5a5f50356142a22ec0c33ff2b5debdf603c80068e1f96069a7a3a8f751 */
select business_date as date_, security_id, 'EUGBR' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-16' and business_date <= date '2025-06-16' and weight_ndo>0 and id_cppib_index = 'EUGBR_GR_USD_0_0' and security_id is not null

/* cppi::37bf7207745d31e64ed89fdbfcc530169ee4c0a43f4dcb3a0880b17164011eb4 */
SELECT * FROM ci_etl_db_dev.ci_capital_pipeline_sentry_unsettled_transactions_transformed
                WHERE CAST(extract_timestamp AS TIMESTAMP) = TIMESTAMP '2025-06-17 13:12:27'

/* cppi::215c15f8bc634a567caade2f82caa85dca16d8ae408816ea6e0160ccc8ff75c3 */
SELECT * FROM (SELECT *
FROM (
  SELECT a.business_date, a.position_key, a.dv01_currency, a.dv01_tenor, a.dv01_cad_value FROM "risk_prod"."rmv_dv01" a WHERE investment_strategy = 'Emerging Markets Fixed Income'
) "custom_sql_query"
LIMIT 0) T LIMIT 0

